from hermes_tools import terminal
cmd = r'''
python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
assert wb.sheetnames == ['Task','Data'], wb.sheetnames
ws=wb['Task']
targets=[]
for start,end in [(12,17),(19,24),(26,31),(35,40),(42,47)]:
    for r in range(start,end+1):
        for c in range(8,13):
            targets.append((r,c))
for c in range(8,13):
    targets.append((50,c))
missing=[]
non_formula=[]
for r,c in targets:
    v=ws.cell(r,c).value
    if v is None:
        missing.append(f'{get_column_letter(c)}{r}')
    elif not (isinstance(v,str) and v.startswith('=')):
        non_formula.append((f'{get_column_letter(c)}{r}',v))
print('Formula target count:', len(targets))
print('Missing targets:', missing)
print('Non-formula targets:', non_formula)
assert not missing
assert not non_formula
# Verify formula patterns exactly for representative and all generated areas
errors=[]
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            if ws.cell(r,c).value != expected:
                errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
for r in range(35,41):
    offset=r-35
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+offset}-{col}{19+offset})/{col}{26+offset}*100'
        if ws.cell(r,c).value != expected:
            errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
stat_expected={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for r,fn in stat_expected.items():
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'={fn}({col}$35:{col}$40)'
        if ws.cell(r,c).value != expected:
            errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
for r,p in [(46,'0.25'),(47,'0.75')]:
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=PERCENTILE({col}$35:{col}$40,{p})'
        if ws.cell(r,c).value != expected:
            errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
for c in range(8,13):
    col=get_column_letter(c)
    expected=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    if ws.cell(50,c).value != expected:
        errors.append((f'{col}50', ws.cell(50,c).value, expected))
print('Formula pattern errors:', len(errors))
for e in errors[:10]: print('ERROR', e)
assert not errors
print('\nSample formulas from each block:')
for addr in ['H12','I13','L17','H19','J22','L24','H26','K30','L31','H35','J38','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    print(f'{addr}: {ws[addr].value}')
wb.close()
PY
'''
print(terminal(cmd, timeout=120, workdir='/root')['output'])
